  std::cout << maxq.top() << ' '; maxq.pop(); }
std::cout << "| ";
while (!minq.empty()) {
  std::cout << minq.top() << ' '; minq.pop(); }

struct Later {  // a has lower priority
  bool operator()(const Event& a,
                  const Event& b) const {
    if (a.time != b.time)
      return a.time > b.time;
    return a.seq > b.seq;  // FIFO on ties
  }
};

